"""Build the one offline candidate catalog. Does not modify the map runtime."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[1]
data=(r/'examples/asset-review-data.json').read_text().replace('<','\\u003c')
html='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WIZAMAP — catalog màu dự kiến</title><style>
*{box-sizing:border-box}body{margin:0;background:#eee4cf;color:#493c2e;font:15px Georgia,serif}header{background:#382b24;color:#f2e5ca;padding:22px 30px}h1{font-size:27px;margin:0 0 10px;font-weight:normal}header p{margin:6px 0;line-height:1.5}nav{padding:15px 24px;display:flex;gap:8px;flex-wrap:wrap;background:#e1d2b6;position:sticky;top:0;z-index:3}button,input,select{font:inherit;padding:9px 12px;border:1px solid #b7a17d;background:#faf4e6;color:#493c2e;border-radius:3px}button{cursor:pointer}button.active{background:#6f443d;color:#fff5dc}input{width:min(330px,90vw)}.controls{padding:16px 24px;display:flex;flex-wrap:wrap;gap:9px;align-items:center}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:18px;padding:0 24px 24px}.card{border:1px solid #c5b390;background:#f8f1e1;border-radius:8px;overflow:hidden}.card img{width:100%;height:215px;object-fit:contain;background:#e8dfc7;padding:12px}.card h2{font-size:18px;margin:14px 16px 9px;font-weight:normal}.card p{margin:8px 16px;font-size:12px;line-height:1.5;overflow-wrap:anywhere}.card button{margin:10px 16px 16px;font-size:12px}small{color:#806f55}.badge{display:inline-block;padding:3px 8px;background:#d7dfc8;color:#4a6149;border-radius:3px}main>p{margin:16px 24px;line-height:1.6}.pager{display:flex;justify-content:center;align-items:center;gap:15px;padding:18px}.report{padding:0 24px 24px;overflow:auto}table{border-collapse:collapse;width:100%;background:#faf4e7;font:13px/1.5 Georgia}th,td{padding:9px;border:1px solid #c7b99b;vertical-align:top;overflow-wrap:anywhere}th{background:#e1d2b6;text-align:left}dialog{width:min(1000px,96vw);max-height:94vh;overflow:auto;border:1px solid #a58d68;border-radius:6px;background:#f7efdd;color:#493c2e;padding:20px}dialog::backdrop{background:#21170e99}.detail-img{width:100%;height:350px;object-fit:contain;background:#e7ddc3}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.note{padding:14px 20px;background:#e3d7bb;border-left:3px solid #8b5c4a;margin:15px 24px;line-height:1.6}footer{text-align:center;padding:20px;font-size:12px;color:#816f52}@media(max-width:600px){header{padding:18px}h1{font-size:23px}.grid{grid-template-columns:1fr;padding:0 15px 15px}.detail-grid{grid-template-columns:1fr}nav{position:static}.detail-img{height:240px}}
</style><header><h1>WIZAMAP · Catalog màu dự kiến</h1><p>__TOTAL__ design · Giữ cụm nguồn; đã xóa toàn bộ cụm mới bị bác bỏ</p><p>BẢN ĐỂ DUYỆT — chưa thay catalog/trees/layout trong runtime Map 2.</p></header><nav id="tabs"><button data-tab="all" class="active">Toàn bộ __TOTAL__</button><button data-tab="clusters">Cụm để bàn</button><button data-tab="trees">Cây</button><button data-tab="demos">Đặt thử trên bàn</button><button data-tab="changes">Giữ / gộp / bỏ</button></nav><div class="controls"><input id="search" placeholder="Tìm tên, design ID hoặc alias..."><select id="view"><option value="">Mọi góc nhìn</option><option>top</option><option>front</option><option>elevation</option><option>side</option></select><select id="category"><option value="">Mọi nhóm</option></select><span id="count"></span><button id="export">Tải JSON đầy đủ</button></div><main id="main"></main><div class="pager"><button id="prev">←</button><span id="page"></span><button id="next">→</button></div><footer>Cùng tên khác nét giữ riêng · Gộp theo hình học/góc nhìn · Không gộp physical instance chỉ vì chung symbol.</footer><dialog id="detail"><button id="close">Đóng</button><div id="detail-body"></div></dialog><script type="application/json" id="catalog-data">'''+data+'''</script><script>
const DATA=JSON.parse(document.getElementById('catalog-data').textContent),$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),src=s=>'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(s)));let tab='all',page=0;const PAGE=24;
function save(text,name,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
for(const c of [...new Set(DATA.assets.map(a=>a.category||'Khác'))].sort()){const o=document.createElement('option');o.value=o.textContent=c;$('#category').append(o)}
function detail(id){const a=DATA.assets.find(a=>a.id===id);$('#detail-body').innerHTML='<h2>'+esc(a.name)+'</h2><img class="detail-img" src="'+src(a.svg)+'"><p>'+esc(a.id)+' · '+esc(a.view)+'</p><p>Nguồn: '+esc(a.sources.join(', '))+'</p><p>Alias công năng: '+esc(a.aliases.join(', ')||'Cụm mới')+'</p>'+(a.parts?'<h3>Thành phần ('+a.parts.length+')</h3><ol>'+a.parts.map(p=>'<li>'+esc(p.name)+' · '+esc(p.designId)+'</li>').join('')+'</ol>':'')+'<h3>Bản sao cùng design đã gộp</h3><ul>'+DATA.changes.filter(c=>c.canonicalId===id&&c.action==='SHARE_SAME_DESIGN').map(c=>'<li>'+esc(c.source+' · '+c.oldId)+'</li>').join('')+'</ul><button id="download-svg">Tải SVG màu</button>';$('#download-svg').onclick=()=>save(a.svg,a.id+'.svg','image/svg+xml');$('#detail').showModal()}
function render(){let q=$('#search').value.toLowerCase(),v=$('#view').value,c=$('#category').value;const match=a=>!q||[a.name,a.id,...(a.aliases||[])].join(' ').toLowerCase().includes(q);let items=DATA.assets.filter(a=>match(a)&&(!v||a.view===v)&&(!c||(a.category||'Khác')===c));if(tab==='clusters')items=items.filter(a=>a.originalId?.startsWith('cluster.')||a.id.startsWith('wm.surface.'));if(tab==='trees')items=items.filter(a=>a.originalId?.startsWith('tree.')||a.originalId==='architecture.tree'||a.id.startsWith('wm.grove.'));
if(tab==='changes'){const changes=DATA.changes.filter(a=>!q||Object.values(a).join(' ').toLowerCase().includes(q));page=Math.max(0,Math.min(page,Math.ceil(changes.length/PAGE)-1));$('#count').textContent=changes.length+' bản ghi nguồn';$('#main').innerHTML='<div class="note"><b>Kết quả lọc:</b> 1.376 bản ghi nguồn → __BASE__ design; gộp __COPIES__ bản sao cùng hình học/góc nhìn, loại 33 bản cây thường cũ khỏi candidate. Cổ thụ và liễu đặc biệt giữ riêng. Không giữ cụm mới → __TOTAL__ design. Không xóa artwork/instance trên 13 Fixed ở lượt này.</div><div class="report"><table><tr><th>Nguồn / ID cũ</th><th>Xử lý</th><th>Design giữ lại</th></tr>'+changes.slice(page*PAGE,(page+1)*PAGE).map(a=>'<tr><td>'+esc(a.source+' · '+a.oldId)+'<br>'+esc(a.name)+'</td><td>'+esc(a.action)+'</td><td>'+esc(a.canonicalId||'Thay bằng cây 259 sau duyệt')+'</td></tr>').join('')+'</table></div>';$('#page').textContent=(page+1)+' / '+Math.max(1,Math.ceil(changes.length/PAGE));return}
if(tab==='demos'){$('#main').innerHTML='<div class="note">Mẫu gắn cụm top vào bàn nguồn C4. Đây là preview surface, chưa thay layout phòng. Bảy cụm front C4 giữ riêng, không dán sai góc vào mặt bàn top.</div><div class="grid">'+DATA.demos.map(a=>'<article class="card"><img style="height:300px" src="'+src(a.svg)+'"><h2>'+esc(a.name)+'</h2><p>'+esc(a.clusterId)+'</p></article>').join('')+'</div>';$('#count').textContent=DATA.demos.length+' mẫu bàn';$('#page').textContent='1 / 1';return}
page=Math.max(0,Math.min(page,Math.ceil(items.length/PAGE)-1));$('#count').textContent=items.length+' design';$('#page').textContent=(page+1)+' / '+Math.max(1,Math.ceil(items.length/PAGE));$('#main').innerHTML=(tab==='clusters'?'<div class="note">Giữ các cụm nguồn; cụm mới bị bác bỏ đã xóa. Mỗi cụm có inventory thành phần và góc nhìn riêng.</div>':tab==='trees'?'<div class="note">Cây thường từ 259 đã có palette màu. Hai cụm không chứa cổ thụ hoặc liễu đặc biệt; các design cây đặc biệt vẫn giữ riêng.</div>':'')+'<div class="grid">'+items.slice(page*PAGE,(page+1)*PAGE).map(a=>'<article class="card"><img loading="lazy" src="'+src(a.svg)+'"><h2>'+esc(a.name)+'</h2><p><span class="badge">'+esc(a.view||'source')+'</span> '+(a.status==='new candidate'?'<b>MỚI</b>':'')+'</p><p>'+esc(a.id)+'</p><p><small>'+esc(a.source)+' · '+(a.coloredBy?'Đã có màu':'Cụm ghép')+'</small></p><button data-id="'+esc(a.id)+'">Xem / tải SVG</button></article>').join('')+'</div>';document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>detail(b.dataset.id));}
$('#tabs').onclick=e=>{const b=e.target.closest('[data-tab]');if(!b)return;tab=b.dataset.tab;page=0;document.querySelectorAll('[data-tab]').forEach(n=>n.classList.toggle('active',n===b));render()};for(const s of ['#search','#view','#category'])$(s).oninput=()=>{page=0;render()};$('#next').onclick=()=>{page++;render()};$('#prev').onclick=()=>{page=Math.max(0,page-1);render()};$('#close').onclick=()=>$('#detail').close();$('#export').onclick=()=>save(JSON.stringify(DATA,null,2),'WIZAMAP-candidate-catalog.json','application/json');render();
</script></html>'''
summary=json.loads((r/'examples/asset-review-data.json').read_text())['summary']
html=html.replace('__TOTAL__',str(summary['totalCandidateDesigns'])).replace('__BASE__',str(summary['keptDesigns'])).replace('__COPIES__',str(summary['sharedCopies']))
(r/'examples/asset-review.html').write_text(html)
print('Offline catalog bytes',len(html.encode()))
